import * as React from "react"
import Seo from "../../components/Seo"
import AuthShell, { AuthLink } from "../../components/auth/AuthShell"
import { ArrowRight } from "../../components/Icons"
import * as s from "../../components/auth/Auth.module.css"

/**
 * "I paid and I cannot get in" — MTC-FCS-035.
 * ============================================================================
 * The screen for the one recovery path that cannot be automated: the email
 * address on the account is wrong, so no link we could send would arrive.
 *
 * ── IT ASKS FOR THE RECOVERY CODE FIRST ────────────────────────────────────
 * Because it is the only thing they can give us that finds the payment without
 * anybody knowing which address was typed. Everything else on the form is a
 * fallback for somebody who did not keep it.
 *
 * ── IT NEVER ASKS FOR CARD DETAILS ─────────────────────────────────────────
 * Not even a last-four. No card field exists anywhere in this codebase and a
 * "prove it is you" box on a help page is exactly how that rule erodes — and
 * how a phishing page learns to look like ours. We find the payment in Stripe
 * from the code; if it comes to it, we ask by phone.
 */

const CannotLogInPage = () => {
  const [form, setForm] = React.useState({
    recoveryCode: "",
    email: "",
    phone: "",
    name: "",
    business: "",
    message: "",
  })
  const [busy, setBusy] = React.useState(false)
  const [done, setDone] = React.useState(null)
  const [error, setError] = React.useState("")

  const set = (key, value) => setForm(prev => ({ ...prev, [key]: value }))

  // Enough to reach them, and enough to go on.
  const reachable = form.email.trim() || form.phone.trim()
  const findable = form.recoveryCode.trim() || form.email.trim() || form.business.trim()

  const submit = async e => {
    e.preventDefault()
    if (busy) return
    setError("")
    setBusy(true)

    try {
      const res = await fetch("/api/support-request", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      })
      const body = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(body.message || "That did not go through. Please try again in a moment.")
        return
      }
      setDone(body)
    } catch {
      setError("That did not go through — check your connection and try again.")
    } finally {
      setBusy(false)
    }
  }

  if (done) {
    return (
      <AuthShell
        title="We have it"
        lead={done.message}
        footer={
          <>
            Back to <AuthLink to="/log-in">logging in</AuthLink>
          </>
        }
      >
        {done.reference ? (
          <p className={s.lead}>
            Your reference is <strong>{done.reference}</strong>. Quote it if you contact us again.
          </p>
        ) : null}
        <p className={s.lead}>
          Nothing has been charged twice and your website is not affected. If you gave us a phone
          number, expect a call rather than an email — an email is the thing that is not reaching
          you.
        </p>
      </AuthShell>
    )
  }

  return (
    <AuthShell
      title="Cannot get in?"
      lead="If you paid and no email ever arrived, the address on the account is probably wrong by a character. Tell us here and we will fix it by hand."
      footer={
        <>
          Remembered it? <AuthLink to="/log-in">Log in</AuthLink>
        </>
      }
    >
      <form onSubmit={submit}>
        <div className={s.fields}>
          <div className={s.field}>
            <label htmlFor="rc-code">Recovery code</label>
            <input
              id="rc-code"
              value={form.recoveryCode}
              onChange={e => set("recoveryCode", e.target.value)}
              placeholder="FCS-7K2M-93QX"
              autoComplete="off"
              spellCheck="false"
              disabled={busy}
            />
            <p className={s.hint}>
              Shown on the screen straight after you paid, and on your receipt. It is how we find
              your payment without needing the email address. Leave it blank if you do not have it.
            </p>
          </div>

          <div className={s.field}>
            <label htmlFor="rc-email">The email you think you used</label>
            <input
              id="rc-email"
              type="email"
              value={form.email}
              onChange={e => set("email", e.target.value)}
              autoComplete="email"
              disabled={busy}
            />
          </div>

          <div className={s.field}>
            <label htmlFor="rc-phone">Phone number</label>
            <input
              id="rc-phone"
              value={form.phone}
              onChange={e => set("phone", e.target.value)}
              autoComplete="tel"
              disabled={busy}
            />
            <p className={s.hint}>The best way to reach you, since email is the problem.</p>
          </div>

          <div className={s.field}>
            <label htmlFor="rc-business">Business name</label>
            <input
              id="rc-business"
              value={form.business}
              onChange={e => set("business", e.target.value)}
              autoComplete="organization"
              disabled={busy}
            />
          </div>

          <div className={s.field}>
            <label htmlFor="rc-message">Anything else</label>
            <textarea
              id="rc-message"
              rows={4}
              value={form.message}
              onChange={e => set("message", e.target.value)}
              disabled={busy}
            />
          </div>
        </div>

        <button
          type="submit"
          className={`btn btn--lg ${s.submit}`}
          disabled={busy || !reachable || !findable}
        >
          {busy ? "Sending…" : "Send this to us"}
          {!busy && <ArrowRight className="btn__arrow" />}
        </button>

        {!reachable ? (
          <p className={s.hint}>Leave an email address or a phone number so we can reply.</p>
        ) : null}

        {error ? <p className={s.error}>{error}</p> : null}
      </form>
    </AuthShell>
  )
}

export const Head = () => (
  <Seo
    title="Cannot log in"
    description="Paid but cannot get into your account? Tell us here and we will fix it."
  />
)

export default CannotLogInPage
